declarations.code:
template <class Out, class T>

concept indirectly_writable =

    requires(Out &&o, T &&t) {
        *o = std::forward<T>(t);

        *std::forward<Out>(o) = std::forward<T>(t);

        const_cast<const std::iter_reference_t<Out> &&>(*o) = std::forward<T>(t);

        const_cast<const std::iter_reference_t<Out> &&>(*std::forward<Out>(o)) =

            std::forward<T>(t);
    };

/* none of the four expressions above are required to be equality-preserving */

examples.code:
#include <iterator>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    static_assert(std::indirectly_writable<int *, int>);
    int values[]{3, 7};
    int *position = values;
    assert(*position == 3);
    ++position;
    assert(*position == 7);
    std::cout << "Checks passed\n";
}
